  /* Celebrate only the native boss-start toast. No requests or game actions. */
  function createBossAnnouncement({ show, hide, quiet }) {
    const seen = new WeakMap();
    let current = null;
    return {
      sync(toast, visible) {
        if (!toast) {
          if (current) {
            hide();
            quiet(current, false);
            current = null;
          }
          return;
        }
        if (!visible) {
          seen.delete(toast);
          quiet(toast, false);
          if (current === toast) {
            hide();
            current = null;
          }
          return;
        }
        const text = toast.textContent.trim();
        if (!text || seen.get(toast) === text) return;
        seen.set(toast, text);
        if (current) {
          hide();
          if (current !== toast) quiet(current, false);
        }
        current = toast;
        quiet(toast, true);
        show(text);
      },
      dismiss() {
        hide();
      },
      dispose() {
        hide();
        if (current) quiet(current, false);
        current = null;
      },
    };
  }
