  /* Local presentations of values already rendered by the native guild pages. */
  function guildNumbers(text) {
    return [...String(text).matchAll(/\d[\d,]*(?:\.\d+)?(?:\s*[KMB]\b)?/gi)]
      .map((m) => {
        const raw = m[0].trim(),
          unit = raw.match(/[KMB]$/i)?.[0].toUpperCase();
        return Number(raw.replace(/[,\sKMB]/gi, "")) * ({ K: 1e3, M: 1e6, B: 1e9 }[unit] || 1);
      })
      .filter(Number.isFinite);
  }
  function guildProgressValues(text) {
    const numbers = guildNumbers(
        String(text)
          .replace(/\bfor level\s+\d+/i, "")
          .replace(/\d+\s*级需/, "需"),
      ),
      current = numbers[0],
      target = numbers.at(-1);
    return numbers.length >= 2 && current >= 0 && target > 0
      ? {
          current,
          target,
          gap: Math.max(0, target - current),
          percent: Math.min(100, (current / target) * 100),
        }
      : null;
  }
  const guildValueRecords = new WeakMap();
  let guildHelpOpen = false;
